import{_ as o,r as n,o as p,c,e as a,a as i,s as l}from"./chunks/framework.CXcwiNg-.js";const _=JSON.parse('{"title":"Конфигурация базы данных - October CMS - 3.x","titleTemplate":false,"description":"Узнайте, как настроить уровень базы данных.","frontmatter":{"subtitle":"Узнайте, как настроить уровень базы данных."},"headers":[{"level":2,"title":"Конфигурация SQLite","slug":"конфигурация-sqlite","link":"#конфигурация-sqlite","children":[]},{"level":2,"title":"Подключения для чтения и записи","slug":"подключения-для-чтения-и-записи","link":"#подключения-для-чтения-и-записи","children":[]},{"level":2,"title":"Длина индексов в MySQL / MariaDB","slug":"длина-индексов-в-mysql-mariadb","link":"#длина-индексов-в-mysql-mariadb","children":[]}],"relativePath":"3.x/ru/setup/database-config.md","filePath":"3.x/ru/setup/database-config.md"}'),r={name:"3.x/ru/setup/database-config.md"};function d(g,s,u,k,q,h){const t=n("pre-heading"),e=n("post-heading");return p(),c("div",null,[a(t),s[0]||(s[0]=i("h1",null,"Конфигурация базы данных",-1)),a(e),s[1]||(s[1]=l(`<p>Конфигурация базы данных вашего приложения находится в файле <code>config/database.php</code>. В этом файле вы можете определить все подключения к базам данных, а также указать, какое подключение должно использоваться по умолчанию. Примеры для всех поддерживаемых систем баз данных приведены в этом файле.</p><h2 id="конфигурация-sqlite"><a href="#конфигурация-sqlite" class="header-anchor">#</a> Конфигурация SQLite</h2><p>Базы данных SQLite используют один файл в файловой системе. Чтобы создать новую базу данных SQLite, используйте команду <code>touch</code>.</p><div class="language-bash extra-class"><pre class="language-bash"><code><span class="token function">touch</span> storage/database.sqlite
</code></pre></div><p>После этого вы можете настроить переменные окружения для использования базы данных, указав абсолютный путь в переменной <code>DB_DATABASE</code>.</p><div class="language-text extra-class"><pre class="language-text"><code>DB_CONNECTION=sqlite
DB_DATABASE=/absolute/path/to/database.sqlite
</code></pre></div><h2 id="подключения-для-чтения-и-записи"><a href="#подключения-для-чтения-и-записи" class="header-anchor">#</a> Подключения для чтения и записи</h2><p>Иногда может потребоваться использовать одно подключение к базе данных для операторов SELECT, а другое — для операторов INSERT, UPDATE и DELETE. Указать, какое подключение используется, легко независимо от того, применяете ли вы прямые запросы, конструктор запросов или модель.</p><p>Чтобы увидеть, как следует настраивать подключения для чтения и записи, рассмотрим следующий пример:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token string single-quoted-string">&#39;mysql&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
    <span class="token string single-quoted-string">&#39;read&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;host&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;192.168.1.1&#39;</span><span class="token punctuation">,</span>
    <span class="token punctuation">]</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;write&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;host&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;196.168.1.2&#39;</span>
    <span class="token punctuation">]</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;driver&#39;</span>    <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;mysql&#39;</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;database&#39;</span>  <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;database&#39;</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;username&#39;</span>  <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;root&#39;</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;password&#39;</span>  <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;&#39;</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;charset&#39;</span>   <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;utf8&#39;</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;collation&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;utf8_unicode_ci&#39;</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;prefix&#39;</span>    <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;&#39;</span><span class="token punctuation">,</span>
<span class="token punctuation">]</span><span class="token punctuation">,</span>
</code></pre></div><p>Обратите внимание, что в массив конфигурации добавлены два ключа: <code>read</code> и <code>write</code>. Оба эти ключа содержат массивы с одним ключом: <code>host</code>. Остальные параметры базы данных для подключений <code>read</code> и <code>write</code> будут объединены из основного массива <code>mysql</code>.</p><p>Нам нужно помещать элементы в массивы <code>read</code> и <code>write</code> только в том случае, если мы хотим переопределить значения из основного массива. Таким образом, в данном случае <code>192.168.1.1</code> будет использоваться как подключение для чтения, а <code>192.168.1.2</code> — как подключение для записи. Учётные данные базы данных, префикс, набор символов и все остальные параметры из основного массива <code>mysql</code> будут общими для обоих подключений.</p><p><a id="oc-index-lengths-using-mysql-mariadb"></a></p><h2 id="длина-индексов-в-mysql-mariadb"><a href="#длина-индексов-в-mysql-mariadb" class="header-anchor">#</a> Длина индексов в MySQL / MariaDB</h2><p>По умолчанию October CMS использует набор символов <code>utf8mb4</code>. Если вы используете версию MySQL старше v5.7.7 или MariaDB старше v10.2.2, вам необходимо вручную настроить длину строк по умолчанию, генерируемую миграциями, чтобы MySQL мог создавать для них индексы. Для настройки длины строк по умолчанию добавьте следующее в файл конфигурации <strong>config/database.php</strong> под ключом <code>connections.mysql</code>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token string single-quoted-string">&#39;mysql&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
    <span class="token comment">// ...</span>
    <span class="token string single-quoted-string">&#39;varcharmax&#39;</span> <span class="token operator">=&gt;</span> <span class="token number">191</span><span class="token punctuation">,</span>
<span class="token punctuation">]</span><span class="token punctuation">,</span>
</code></pre></div>`,16))])}const b=o(r,[["render",d]]);export{_ as __pageData,b as default};
